script:
let removed_item = [];
function apply_filter(field_name, filter_on, frm, filter_value, withoutFilter = false) {
  frm.fields_dict[field_name].get_query = () => {
    if (withoutFilter) {
      return {
        filters: {},
        page_length: 1000
      };
    }
    return {
      filters: {
        [filter_on]: filter_value || frm.doc[filter_on] || `please select ${filter_on}`,
      },
      page_length: 1000
    };
  }
}
const hide_advance_search=(frm, list)=> {
    for (let item of list) {
      frm.set_df_property(item, 'only_select', true);
    }
}
const extend_options_length=(frm, fields) => {
    fields?.forEach((field) => {
      frm.set_query(field, () => {
        return { page_length: 1000 };
      });
    })
};

frappe.ui.form.on('Collective', {
	refresh(frm) {
        hide_advance_search(frm , ['state','city'])
        extend_options_length(frm , ['state', 'city'])
        apply_filter("city", "State", frm, frm.doc.state);
        frm.set_value('number_of_members',frm?.doc?.table_aogw?.length)
        frm.set_value('number_of_actions',frm?.doc?.table_nfzi?.length)
        if(frappe.user_roles.includes("MIS executive")){
            frm.set_df_property('table_aogw','cannot_add_rows',true)
        }
	},
	before_save(frm){
	    frm.doc.deleted_rows = removed_item
	},
	date_of_formation:function(frm){
    if (new Date(frm.doc.date_of_formation) > new Date(frappe.datetime.get_today())) {
        frm.doc.date_of_formation = ''
        frm.set_value("date_of_formation", '')
        refresh_field('date_of_formation')
        frappe.throw(__("<b>Date of formation</b> can't be greater than today's date"))
        }
    },
    state:function(frm){
        apply_filter("city", "State", frm, frm.doc.state)
    },
})
frappe.ui.form.on('Collective Members List', {
	refresh(frm) {
	},
	table_aogw_remove:async function(frm, cdt, cdn){
     removed_item.push(cdn)
   },
   table_aogw_add:async function(frm, cdt, cdn){
   }
})

frappe.ui.form.on("Infrastructural Success", {
    refresh: function(frm) {
        frm.set_query("city", function() {
            return { filters: { state: frm.doc.state } };
        });
        calculate_summary(frm);
    },
    state: function(frm) {
        frm.set_value("city", "");
    },
    onload: function(frm) {
        calculate_summary(frm);
    }
});

frappe.ui.form.on("Infrastructure Item", {
    infrastructure_items_add: function(frm) { calculate_summary(frm); },
    infrastructure_items_remove: function(frm) { calculate_summary(frm); },
    status: function(frm) { calculate_summary(frm); }
});

function calculate_summary(frm) {
    var items = frm.doc.infrastructure_items || [];
    var total = items.length;
    var functional = items.filter(function(d) { return d.status === "Fully Functional"; }).length;
    var score = total > 0 ? (functional / total) * 100 : 0;
    frm.set_value("total_facilities_assessed", total);
    frm.set_value("functional_count", functional);
    frm.set_value("overall_score", Math.round(score * 100) / 100);
}
